def need(ok,message):
    if not ok:raise ValueError(message)

def payload_files():
    blob=base64.b85decode(PAYLOAD);need(hashlib.sha256(blob).hexdigest()==PAYLOAD_SHA256,'Payload hash changed')
    files={}
    with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)),mode='r:') as tar:
        members=tar.getmembers();need(len(members)==len(SOURCE_MANIFEST) and {x.name for x in members}==set(SOURCE_MANIFEST),'Source inventory changed')
        for item in members:
            name=Path(item.name);need(item.isfile() and not name.is_absolute() and '..' not in name.parts and item.name not in files,'Unsafe source member')
            data=tar.extractfile(item).read();need(hashlib.sha256(data).hexdigest()==SOURCE_MANIFEST[item.name],'Source digest changed');files[item.name]=data
    return files

def embedded(name):
    value=types.ModuleType('_transient_speed_embedded_'+name)
    files=payload_files()
    exec(compile(files['tools/'+name+'.py'],'<verified-'+name+'>','exec'),value.__dict__)
    if name=='runtime_policy':value._VERIFIED_PAYLOAD_FILES=files
    return value

def unpack(destination):
    guards=embedded('path_guards');destination=guards.no_symlink_ancestors(destination);files=payload_files();owner=destination/'.source-owner.json'
    if destination.exists():
        need(destination.is_dir(),'Extraction root is not a directory');guards.reject_tree_symlinks(destination)
        if any(destination.iterdir()):need(owner.is_file() and json.loads(owner.read_text())=={'payload_sha256':PAYLOAD_SHA256},'Unowned extracted source')
        actual={str(p.relative_to(destination)) for p in destination.rglob('*') if p.is_file()}
        need(actual<=set(SOURCE_MANIFEST)|{'.source-owner.json'},'Unexpected extracted source files')
    for name,data in files.items():
        target=guards.no_symlink_ancestors(destination/name);need(target.is_relative_to(destination),'Source target escaped root')
        need(not target.exists() or target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest()==SOURCE_MANIFEST[name],'Modified extracted source')
    destination.mkdir(parents=True,exist_ok=True)
    if not owner.exists():owner.write_text(json.dumps({'payload_sha256':PAYLOAD_SHA256})+'\n')
    for name,data in files.items():
        target=destination/name;target.parent.mkdir(parents=True,exist_ok=True)
        if not target.exists():target.write_bytes(data)
    return destination

def run_native(root,arguments,origin):
    # Exact production ownership supervisor. No /proc fallback or test adapter.
    protocol=json.loads((root/'browser/protocol.json').read_bytes());budget=protocol['budgets']
    need(time.monotonic()<=origin+budget['pre_browser_eligibility_seconds'],'Pre-browser eligibility cutoff reached')
    spec=importlib.util.spec_from_file_location('_transient_speed_native_owner',root/'tools/process_guard.py');owner=importlib.util.module_from_spec(spec);spec.loader.exec_module(owner)
    deadline=origin+budget['whole_job_seconds']
    owner.run_owned([sys.executable,str(root/'runner.py'),*arguments],cwd=root,deadline=deadline,cleanup_deadline=deadline,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'))

def main():
    started=time.monotonic()
    need(not sys.flags.optimize,'Assertions must remain enabled')
    parser=argparse.ArgumentParser(description=__doc__,allow_abbrev=False)
    modes=parser.add_mutually_exclusive_group()
    for mode in ('plan','self-test','prepare','execute-browser','extract-only'):modes.add_argument('--'+mode,action='store_true')
    for mode in ('validate-report','validate-public-build','render-report'):modes.add_argument('--'+mode,type=Path)
    parser.add_argument('--private',type=Path,default=Path('transient-speed-output'));parser.add_argument('--cache',type=Path,default=Path('transient-speed-cache'))
    parser.add_argument('--build-proof',type=Path);parser.add_argument('--html-output',type=Path);parser.add_argument('--ci-start-monotonic',type=float)
    args=parser.parse_args()
    if args.ci_start_monotonic is not None:need(math.isfinite(args.ci_start_monotonic) and 0<=args.ci_start_monotonic<=started,'Invalid or future monotonic origin')
    if args.render_report:need(args.html_output is not None,'--html-output required')
    native=args.prepare or args.execute_browser
    if native:
        embedded('runtime_policy').require_execution_allowed()
        budget=json.loads(payload_files()['browser/protocol.json'])['budgets']
        origin=started if args.ci_start_monotonic is None else args.ci_start_monotonic
        need(time.monotonic()<=origin+budget['pre_browser_eligibility_seconds'],'Pre-browser eligibility cutoff reached')
    remaining=[]
    for mode in ('plan','self-test','prepare','execute-browser','validate-report','validate-public-build','render-report'):
        value=getattr(args,mode.replace('-','_'))
        if value:remaining+=['--'+mode]+([] if value is True else [str(value.absolute())])
    for mode in ('build-proof','html-output'):
        value=getattr(args,mode.replace('-','_'))
        if value is not None:remaining+=['--'+mode,str(value.absolute())]
    guards=embedded('path_guards');private=guards.no_symlink_ancestors(args.private);cache=guards.no_symlink_ancestors(args.cache)
    source=private.parent/('transient-speed-source-'+PAYLOAD_SHA256[:16]);guards.require_disjoint(private,cache)
    guards.validate_root(private,source);guards.validate_root(cache,source)
    launcher=guards.no_symlink_ancestors(Path(__file__).absolute())
    need(not any(launcher==root or launcher.is_relative_to(root) for root in (private,cache)),'Output overlaps standalone source')
    root=unpack(source)
    if args.extract_only:print(json.dumps({'source_only':True,'payload_sha256':PAYLOAD_SHA256,'files':len(SOURCE_MANIFEST),'execution_enabled_source':embedded('runtime_policy').status()['execution_enabled_source'],'actual_execution_performed':False}));return
    # Offline modes run in-process. Native orchestration always uses the exact
    # production supervisor, independently of this offline convenience.
    sys.dont_write_bytecode=True
    spec=importlib.util.spec_from_file_location('_transient_speed_offline_runner',root/'runner.py');runner=importlib.util.module_from_spec(spec);spec.loader.exec_module(runner)
    origin=['--ci-start-monotonic',str(args.ci_start_monotonic)] if args.ci_start_monotonic is not None else ['--launcher-start-monotonic',str(started)]
    arguments=['--private',str(private),'--cache',str(cache),*origin,*remaining]
    if native:run_native(root,arguments,started if args.ci_start_monotonic is None else args.ci_start_monotonic)
    else:runner.main(arguments)

if __name__=='__main__':main()
